INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2195371, 301217, 51533, '<td valign="top">the kids are cute, I admit, but what connection with "confort"? they just want you to finish the shot already and go out play!:) the blanket is ugly, the light is bad (red eyes!!!) and the composition is a little offcenter in an unpleasing way; I voted 3 just for the great feat of getting 4 nice kids to sit still long enough to take the picture!</td>', 'the kids are cute, I admit, but what connection with "confort"? they just want you to finish the shot already and go out play!:) the blanket is ugly, the light is bad (red eyes!!!) and the composition is a little offcenter in an unpleasing way; I voted 3 just for the great feat of getting 4 nice kids to sit still long enough to take the picture!', '2006-03-02 06:44:06.000000', NULL, 1),
(2195373, 301024, 51533, '<td valign="top">I can barely understand what is hapenning. As I understand it, it would do well in a torture challenge</td>', 'I can barely understand what is hapenning. As I understand it, it would do well in a torture challenge', '2006-03-02 06:45:37.000000', NULL, 1),
(2195375, 299627, 52675, '<td valign="top">I have a problem with these smaller photos.  Can''t see detail.</td>', 'I have a problem with these smaller photos.  Can''t see detail.', '2006-03-02 06:46:47.000000', NULL, 1),
