(2195400, 301448, 51533, '<td valign="top">the expression is a bit too sad, confort bear not working? nice picture, good composition</td>', 'the expression is a bit too sad, confort bear not working? nice picture, good composition', '2006-03-02 07:07:19.000000', NULL, 1),
(2195402, 300871, 38032, '<td valign="top">I like how you chose to light this.  THe minimal content is also effective.</td>', 'I like how you chose to light this.  THe minimal content is also effective.', '2006-03-02 07:07:42.000000', NULL, 1),
(2195403, 299865, 51533, '<td valign="top">just naming it "comfort" not enough</td>', 'just naming it "comfort" not enough', '2006-03-02 07:08:13.000000', NULL, 1),
(2195407, 299993, 38032, '<td valign="top">I think this is really close to being at the top .. The lighting is cool ... the problem IMO here but the crop is strange and the detail and ice cubes beg for just a wee more light ... of course monitors are all different so ...  Anyway, I like the idea and the lighting but if I were gonna print a poster like that I would add just a bt of content below on this. 6</td>', 'I think this is really close to being at the top .. The lighting is cool ... the problem IMO here but the crop is strange and the detail and ice cubes beg for just a wee more light ... of course monitors are all different so ...  Anyway, I like the idea and the lighting but if I were gonna print a poster like that I would add just a bt of content below on this. 6', '2006-03-02 07:12:35.000000', NULL, 1),
(2195408, 300581, 51533, '<td valign="top">the image has no subject; looks like a total accidental snapshot, just for the sake of some red sky; the objects in the foregroung wich I guess are trees, are annoing; that man is just passing by and even the sail doesen''t look interesting, due to total lack of composition; rays from sun look bizarre; I can see no comfort in it</td>', 'the image has no subject; looks like a total accidental snapshot, just for the sake of some red sky; the objects in the foregroung wich I guess are trees, are annoing; that man is just passing by and even the sail doesen''t look interesting, due to total lack of composition; rays from sun look bizarre; I can see no comfort in it', '2006-03-02 07:13:05.000000', NULL, 1),
(2195410, 301529, 38032, '<td valign="top">There we go ... the colors are great here!!!!  Can''t say it''s the most original idea (commercials etc), but it is well executed for sure!  8</td>', 'There we go ... the colors are great here!!!!  Can''t say it''s the most original idea (commercials etc), but it is well executed for sure!  8', '2006-03-02 07:13:56.000000', NULL, 1),
(2195413, 300901, 38032, '<td valign="top">YES -- I have an 11month old and her sleep is great comfort ... this is a beautiful image and baby.  I know dpc voters typically vote-down babies but this is really nice and fitting for those that understand :) .. I also realize that photographic a sleeping baby is not as easy as it looks!  9</td>', 'YES -- I have an 11month old and her sleep is great comfort ... this is a beautiful image and baby.  I know dpc voters typically vote-down babies but this is really nice and fitting for those that understand :) .. I also realize that photographic a sleeping baby is not as easy as it looks!  9', '2006-03-02 07:16:03.000000', NULL, 1),
(2195415, 301518, 38032, '<td valign="top">I think this works.  Not something everyone wants to look at necessarilly :) ...but definitely fitting for the challenge and a neat perspective.</td>', 'I think this works.  Not something everyone wants to look at necessarilly :) ...but definitely fitting for the challenge and a neat perspective.', '2006-03-02 07:17:49.000000', NULL, 1),
(2195418, 299668, 38032, '<td valign="top">Successfully shooting into the sun ... very nice.  Not sure how comforting I think it ios but I am not judging too much on that fact for this challenge.  In other words you could have built this bridge , supplying your family with millions of dollars :) ... that yould be comforting!</td>', 'Successfully shooting into the sun ... very nice.  Not sure how comforting I think it ios but I am not judging too much on that fact for this challenge.  In other words you could have built this bridge , supplying your family with millions of dollars :) ... that yould be comforting!', '2006-03-02 07:19:48.000000', NULL, 1),
(2195421, 301209, 53572, '<td valign="top">very nice composition, colour and detail.  could it have been a little sharper?</td>', 'very nice composition, colour and detail.  could it have been a little sharper?', '2006-03-02 07:24:18.000000', NULL, 1),
(2195422, 300180, 53572, '<td valign="top">deep, subtle.  i like the dark, underexposure.</td>', 'deep, subtle.  i like the dark, underexposure.', '2006-03-02 07:24:57.000000', NULL, 1),
(2195423, 300698, 53572, '<td valign="top">took me a second to figure it, but when i did i smilled. nicely done</td>', 'took me a second to figure it, but when i did i smilled. nicely done', '2006-03-02 07:25:44.000000', NULL, 1),
(2195425, 300560, 53130, '<td valign="top">surprised to see this photo under this caption.........</td>', 'surprised to see this photo under this caption.........', '2006-03-02 07:26:16.000000', NULL, 1),
