(2198618, 299264, 53964, '<td valign="top">Beautiful sharpness and lighting to capture the detail of the rose. Maybe a touch more to the right?</td>', 'Beautiful sharpness and lighting to capture the detail of the rose. Maybe a touch more to the right?', '2006-03-03 18:09:22.000000', NULL, 1),
(2198621, 299670, 53964, '<td valign="top">Lol, LOVE those ears!</td>', 'Lol, LOVE those ears!', '2006-03-03 18:10:13.000000', NULL, 1),
(2198623, 301009, 53964, '<td valign="top">I thought it was probably the nightcap.</td>', 'I thought it was probably the nightcap.', '2006-03-03 18:11:17.000000', NULL, 1),
(2198638, 301568, 53964, '<td valign="top">The knitting is gorgeous, the whole scene relaxing and cozy. However, I would prefer to see the cup in better focus, since it''s half of the main subject matter, and it moving an inch one way or the other to hide that bit of table leg or show more of it. I find the tiny sliver distracting. <br/>On the whole though, I like it.</td>', 'The knitting is gorgeous, the whole scene relaxing and cozy. However, I would prefer to see the cup in better focus, since it''s half of the main subject matter, and it moving an inch one way or the other to hide that bit of table leg or show more of it. I find the tiny sliver distracting. On the whole though, I like it.', '2006-03-03 18:14:53.000000', NULL, 1),
(2198672, 299924, 53964, '<td valign="top">This has GOT to be taken by a man! ;)</td>', 'This has GOT to be taken by a man! ;)', '2006-03-03 18:29:40.000000', NULL, 1),
