(2198748, 301217, 36382, '<td valign="top">I like this and well done on getting four kids to co-operate all at the same time.  I think you could have improved it further by maybe having them all in white shirts, certainly the red tshirt is a little distracting especially the writing.  Also a plain blanked might have worked better.  Still a good job.  All four kids have great expressions. 7</td>', 'I like this and well done on getting four kids to co-operate all at the same time.  I think you could have improved it further by maybe having them all in white shirts, certainly the red tshirt is a little distracting especially the writing.  Also a plain blanked might have worked better.  Still a good job.  All four kids have great expressions. 7', '2006-03-03 19:16:07.000000', NULL, 1),
(2198752, 300452, 36382, '<td valign="top">The boats in the background suggest an imminent departure.  Nice muted colors too.</td>', 'The boats in the background suggest an imminent departure.  Nice muted colors too.', '2006-03-03 19:19:50.000000', NULL, 1),
(2198753, 301789, 51802, '<td valign="top">I love the lighting in this shot!  The reflections of the candles add a lot.  Hope this does well for you.</td>', 'I love the lighting in this shot!  The reflections of the candles add a lot.  Hope this does well for you.', '2006-03-03 19:20:47.000000', NULL, 1),
(2198756, 301660, 51802, '<td valign="top">I imagine you are going to get dinged for cropping the persons head, but I like it.</td>', 'I imagine you are going to get dinged for cropping the persons head, but I like it.', '2006-03-03 19:22:16.000000', NULL, 1),
