INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2204307, 300222, 54583, '<td valign="top">This is a great closeup photo with appropriate sharpness and framing. Im just not sure if it says 100% "comfort".  The beautiful eyes of the dog give much more emotion. They say to me  "I''ve had a great day  but now Im tired''</td>', 'This is a great closeup photo with appropriate sharpness and framing. Im just not sure if it says 100% "comfort".  The beautiful eyes of the dog give much more emotion. They say to me  "I''ve had a great day  but now Im tired''', '2006-03-06 12:28:19.000000', NULL, 1),
(2204315, 301738, 54583, '<td valign="top">Beautiful. It must have been even better seeing it in reality</td>', 'Beautiful. It must have been even better seeing it in reality', '2006-03-06 12:30:37.000000', NULL, 1),
