(2204337, 301801, 54583, '<td valign="top">Im not such a big fan of black and white photos, but this could only work this way.   A nice touch with the chipped paint on the window sill</td>', 'Im not such a big fan of black and white photos, but this could only work this way.   A nice touch with the chipped paint on the window sill', '2006-03-06 12:37:29.000000', NULL, 1),
(2204340, 301830, 40217, '<td valign="top">The design on the glass makes that area of the picture look pixilated. Perhaps a smooth finish on the glass would eliminate that?</td>', 'The design on the glass makes that area of the picture look pixilated. Perhaps a smooth finish on the glass would eliminate that?', '2006-03-06 12:38:25.000000', NULL, 1),
(2204347, 299653, 54583, '<td valign="top">Yes this is very inviting. You have chosen a great  angle and not too much bench. Fits the subject `comfort´ perfectly</td>', 'Yes this is very inviting. You have chosen a great  angle and not too much bench. Fits the subject `comfort´ perfectly', '2006-03-06 12:41:26.000000', NULL, 1),
